/**
 * Responsive image sets generated by `npm run images` (scripts/optimize-images.mjs).
 * Only URL strings are imported, so this module adds no meaningful bundle weight.
 */

export interface ImageSource {
  width: number;
  avif: string;
  webp: string;
  jpg: string;
}

export interface ResponsiveImage {
  sources: ImageSource[];
  /** Intrinsic size of the largest variant, used for width/height attributes. */
  width: number;
  height: number;
}

const files = import.meta.glob<string>('./images/*.{avif,webp,jpg}', {
  eager: true,
  query: '?url',
  import: 'default',
});

function file(name: string): string {
  const url = files[`./images/${name}`];
  if (!url) throw new Error(`Missing image "${name}". Run \`npm run images\`.`);
  return url;
}

function imageSet(name: string, widths: number[], width: number, height: number): ResponsiveImage {
  return {
    width,
    height,
    sources: widths.map((w) => ({
      width: w,
      avif: file(`${name}-${w}.avif`),
      webp: file(`${name}-${w}.webp`),
      jpg: file(`${name}-${w}.jpg`),
    })),
  };
}

export const HERO_BRIDGE = imageSet('hero-bridge', [640, 960, 1280, 1758], 1758, 878);

export const BRIDGE_FIGURES = imageSet('bridge-figures', [400, 800], 800, 400);
